const data = msg.payload;

// Pastikan payload memiliki struktur telemetry
if (!data || !data.metrics || !data.device_id) {
    node.warn("Format telemetry tidak valid");
    return null;
}

msg.measurement = "coldchain_telemetry";

msg.payload = [
    {
        temp_c: Number(data.metrics.temp_c),
        humidity_pct: Number(data.metrics.humidity_pct),
        door_open: Boolean(data.metrics.door_open),
        battery_pct: Number(data.metrics.battery_pct),
        rssi_dbm: Number(data.metrics.rssi_dbm)
    },
    {
        device_id: data.device_id,
        domain: data.domain,
        gedung: data.gedung,
        ruang: data.ruang
    }
];

msg.timestamp = data.ts;

return msg;

const data = msg.payload;

if (!data || !data.device_id || !data.status) {
    return null;
}

if (!["online", "offline"].includes(data.status)) {
    return null;
}

msg.headers = {
    "Content-Type": "application/json",
    "X-API-Key": env.get("API_KEY")
};

msg.payload = {
    device_id: data.device_id,
    status: data.status,
    ts: data.ts || Date.now()
};

return msg;

const data = msg.payload;

if (!data || !data.metrics || !data.device_id) {
    node.warn("Data telemetry tidak valid");
    return null;
}

const deviceId = String(data.device_id);
const temp = Number(data.metrics.temp_c);

if (!Number.isFinite(temp)) {
    node.warn("Nilai suhu tidak valid");
    return null;
}

let states = flow.get("temperatureAlertStatesV3") || {};
let state = states[deviceId] || {
    warningSent: false,
    warningPending: false,
    highSent: false,
    highPending: false,
    highSince: null
};

const now = Date.now();

if (temp <= 6) {
    states[deviceId] = {
        warningSent: false,
        warningPending: false,
        highSent: false,
        highPending: false,
        highSince: null
    };
    flow.set("temperatureAlertStatesV3", states);
    node.warn("SUHU NORMAL: " + deviceId);
    return null;
}

if (temp > 8) {
    if (state.highSince === null) {
        state.highSince = now;
    }
} else {
    state.highSince = null;
    state.highSent = false;
    state.highPending = false;
}

if (!state.warningSent && !state.warningPending) {
    state.warningPending = true;
    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_WARN";
    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_WARN",
        severity: "warning",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 6°C`,
        metadata: { temp_c: temp, threshold_c: 6 }
    };
    return msg;
}

if (
    temp > 8 &&
    state.highSince !== null &&
    !state.highSent &&
    !state.highPending &&
    now - state.highSince >= 120000
) {
    state.highPending = true;
    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_HIGH";
    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_HIGH",
        severity: "critical",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 8°C selama 2 menit`,
        metadata: { temp_c: temp, threshold_c: 8, duration_seconds: 120 }
    };
    return msg;
}

states[deviceId] = state;
flow.set("temperatureAlertStatesV3", states);
return null;

const deviceId = msg.alertDeviceId;
const alertType = msg.alertType;

if (!deviceId || !alertType) {
    node.warn("Identitas alert tidak ditemukan pada respons HTTP");
    return msg;
}

let states = flow.get("temperatureAlertStatesV3") || {};
let state = states[deviceId];

if (!state) {
    node.warn("Status perangkat tidak ditemukan: " + deviceId);
    return msg;
}

const success =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300;

if (alertType === "TEMP_WARN") {
    state.warningPending = false;
    if (success) state.warningSent = true;
}

if (alertType === "TEMP_HIGH") {
    state.highPending = false;
    if (success) state.highSent = true;
}

states[deviceId] = state;
flow.set("temperatureAlertStatesV3", states);

if (success) {
    node.warn("ALERT BERHASIL: " + alertType + " - " + deviceId);
} else {
    node.warn({
        message: "ALERT GAGAL - akan dicoba kembali pada telemetry berikutnya",
        device_id: deviceId,
        alert_type: alertType,
        statusCode: msg.statusCode,
        error: msg.error,
        response: msg.payload
    });
}

return msg;

const data = msg.payload;

if (!data || !data.metrics || !data.device_id) return null;

const deviceId = String(data.device_id);
const temp = Number(data.metrics.temp_c);
if (!Number.isFinite(temp)) return null;

let recovery = flow.get("temperatureRecoveryV3") || {};
let state = recovery[deviceId] || { recovered: false, pending: false };

if (temp <= 6 && !state.recovered && !state.pending) {
    state.pending = true;
    recovery[deviceId] = state;
    flow.set("temperatureRecoveryV3", recovery);

    msg.method = "POST";
    msg.url = `http://backend:8000/api/v1/internal/alerts/resolve-device/${encodeURIComponent(deviceId)}`;
    msg.alertDeviceId = deviceId;
    msg.alertType = "RECOVERY";
    msg.headers = {
        "Content-Type": "application/json",
        "X-API-Key": env.get("API_KEY")
    };
    msg.payload = {};
    return msg;
}

if (temp > 6) {
    state.recovered = false;
    state.pending = false;
}

recovery[deviceId] = state;
flow.set("temperatureRecoveryV3", recovery);
return null;

const deviceId = msg.alertDeviceId;

if (!deviceId) {
    node.warn("Identitas perangkat pemulihan tidak ditemukan");
    return msg;
}

let recovery = flow.get("temperatureRecoveryV3") || {};
let state = recovery[deviceId] || { recovered: false, pending: false };

const success =
    !msg.error &&
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300;

state.pending = false;
if (success) {
    state.recovered = true;
    node.warn("ALERT DIPULIHKAN: " + deviceId);
} else {
    state.recovered = false;
    node.warn({
        message: "PEMULIHAN GAGAL - akan dicoba kembali",
        device_id: deviceId,
        statusCode: msg.statusCode,
        error: msg.error,
        response: msg.payload
    });
}

recovery[deviceId] = state;
flow.set("temperatureRecoveryV3", recovery);
return msg;

const data = msg.payload;

// Validasi telemetry
if (!data || !data.metrics || !data.device_id) {
    node.warn("Data telemetry tidak valid");
    return null;
}

const deviceId = data.device_id;
const temp = Number(data.metrics.temp_c);

if (!Number.isFinite(temp)) {
    node.warn("Nilai suhu tidak valid");
    return null;
}

// Status baru V3
let states = flow.get("temperatureAlertStatesV3") || {};

let state = states[deviceId] || {
    warningSent: false,
    warningPending: false,
    highSent: false,
    highPending: false,
    highSince: null
};

const now = Date.now();

// Suhu normal: reset status
if (temp <= 6) {
    states[deviceId] = {
        warningSent: false,
        warningPending: false,
        highSent: false,
        highPending: false,
        highSince: null
    };

    flow.set("temperatureAlertStatesV3", states);
    node.warn("SUHU NORMAL: " + deviceId);
    return null;
}

// Mulai hitung durasi suhu tinggi
if (temp > 8) {
    if (state.highSince === null) {
        state.highSince = now;
    }
} else {
    state.highSince = null;
    state.highSent = false;
    state.highPending = false;
}

// TEMP_WARN: suhu > 6°C
if (!state.warningSent && !state.warningPending) {
    state.warningPending = true;

    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    node.warn("MENGIRIM TEMP_WARN: " + deviceId);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_WARN";

    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_WARN",
        severity: "warning",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 6°C`,
        metadata: {
            temp_c: temp,
            threshold_c: 6
        }
    };

    return msg;
}

// TEMP_HIGH: suhu > 8°C selama 2 menit
if (
    temp > 8 &&
    state.highSince !== null &&
    !state.highSent &&
    !state.highPending &&
    now - state.highSince >= 120000
) {
    state.highPending = true;

    states[deviceId] = state;
    flow.set("temperatureAlertStatesV3", states);

    node.warn("MENGIRIM TEMP_HIGH: " + deviceId);

    msg.method = "POST";
    msg.url = "http://backend:8000/api/v1/internal/alerts";
    msg.alertDeviceId = deviceId;
    msg.alertType = "TEMP_HIGH";

    msg.payload = {
        device_id: deviceId,
        alert_type: "TEMP_HIGH",
        severity: "critical",
        message: `Suhu ${temp.toFixed(2)}°C melebihi batas 8°C selama 2 menit`,
        metadata: {
            temp_c: temp,
            threshold_c: 8,
            duration_seconds: 120
        }
    };

    return msg;
}

// Simpan status
states[deviceId] = state;
flow.set("temperatureAlertStatesV3", states);

return null;

const data = msg.payload;

if (!data || !data.metrics || !data.device_id) {
    return null;
}

const deviceId = data.device_id;
const temp = Number(data.metrics.temp_c);

if (!Number.isFinite(temp)) {
    return null;
}

let recovered = flow.get("temperatureRecoveredV2") || {};

if (temp <= 6 && !recovered[deviceId]) {
    recovered[deviceId] = true;
    flow.set("temperatureRecoveredV2", recovered);

    msg.method = "POST";
    msg.url = `http://backend:8000/api/v1/internal/alerts/resolve-device/${deviceId}`;

    msg.headers = {
        "Content-Type": "application/json",
        "X-API-Key": env.get("API_KEY")
    };

    msg.payload = {};

    return msg;
}

if (temp > 6) {
    recovered[deviceId] = false;
    flow.set("temperatureRecoveredV2", recovered);
}

return null;

const deviceId = msg.alertDeviceId;
const alertType = msg.alertType;

if (!deviceId || !alertType) {
    node.warn("Identitas alert tidak ditemukan");
    return msg;
}

let states = flow.get("temperatureAlertStatesV3") || {};
let state = states[deviceId];

if (!state) {
    node.warn("Status perangkat tidak ditemukan: " + deviceId);
    return msg;
}

const success =
    Number(msg.statusCode) >= 200 &&
    Number(msg.statusCode) < 300;

if (alertType === "TEMP_WARN") {
    state.warningPending = false;
    if (success) {
        state.warningSent = true;
    }
}

if (alertType === "TEMP_HIGH") {
    state.highPending = false;
    if (success) {
        state.highSent = true;
    }
}

states[deviceId] = state;
flow.set("temperatureAlertStatesV3", states);

if (success) {
    node.warn("ALERT BERHASIL: " + alertType + " - " + deviceId);
} else {
    node.warn({
        message: "ALERT GAGAL",
        device_id: deviceId,
        alert_type: alertType,
        statusCode: msg.statusCode,
        response: msg.payload
    });
}

return msg;
